import numpy as np
from collections import deque

def find_rectangles(grid, color, h_rect, w_rect):
    """Find all rectangular regions of a given size"""
    h, w = grid.shape
    rectangles = []

    for r in range(h - h_rect + 1):
        for c in range(w - w_rect + 1):
            is_uniform = True
            for dr in range(h_rect):
                for dc in range(w_rect):
                    if grid[r+dr, c+dc] != color:
                        is_uniform = False
                        break
                if not is_uniform:
                    break
            if is_uniform:
                rectangles.append((r, c, h_rect, w_rect))

    return rectangles

