# Now check each one: does it have a full wall on one side?
def check_wall_and_edges(rect, grid):
    r, c, h_rect, w_rect = rect
    walls = {}

    # Check top wall (row r-1, cols c to c+w_rect-1)
    if r > 0:
        top_wall = [grid[r-1, k] for k in range(c, c+w_rect)]
        walls['top'] = ('all_foreground', top_wall) if all(x == 4 for x in top_wall) else ('mixed/bg', top_wall)

    # Check bottom wall (row r+h_rect, cols c to c+w_rect-1)
    if r + h_rect < grid.shape[0]:
        bot_wall = [grid[r+h_rect, k] for k in range(c, c+w_rect)]
        walls['bottom'] = ('all_foreground', bot_wall) if all(x == 4 for x in bot_wall) else ('mixed/bg', bot_wall)

    # Check left wall (col c-1, rows r to r+h_rect-1)
    if c > 0:
        left_wall = [grid[k, c-1] for k in range(r, r+h_rect)]
        walls['left'] = ('all_foreground', left_wall) if all(x == 4 for x in left_wall) else ('mixed/bg', left_wall)

    # Check right wall
    if c + w_rect < grid.shape[1]:
        right_wall = [grid[k, c+w_rect] for k in range(r, r+h_rect)]
        walls['right'] = ('all_foreground', right_wall) if all(x == 4 for x in right_wall) else ('mixed/bg', right_wall)

    # Check edges
    edges = {'top': r == 0, 'bottom': r + h_rect == grid.shape[0], 'left': c == 0, 'right': c + w_rect == grid.shape[1]}
    return walls, edges

