import numpy as np

demo_input_arr = np.array(demo_input)

def find_max_rect_with_wall(grid, bg_color=9, wall_color=4):
    """Find the largest rectangular region of bg that has a complete wall"""
    h, w = grid.shape

    best_rect = None
    best_size = 0

    # Check all possible rectangles
    for r1 in range(h):
        for r2 in range(r1, h):
            for c1 in range(w):
                for c2 in range(c1, w):
                    # Check if rectangle is uniform bg
                    is_bg = True
                    for r in range(r1, r2+1):
                        for c in range(c1, c2+1):
                            if grid[r,c] != bg_color:
                                is_bg = False
                                break
                        if not is_bg:
                            break

                    if not is_bg:
                        continue

                    # Check for complete walls
                    rect_area = (r2-r1+1)*(c2-c1+1)
                    has_complete_wall = False

                    # Left wall
                    if c1 > 0:
                        left_wall_ok = all(grid[r,c1-1] == wall_color for r in range(r1, r2+1))
                        if left_wall_ok:
                            has_complete_wall = True

                    # Right wall
                    if c2 + 1 < w:
                        right_wall_ok = all(grid[r,c2+1] == wall_color for r in range(r1, r2+1))
                        if right_wall_ok:
                            has_complete_wall = True

                    # Top wall
                    if r1 > 0:
                        top_wall_ok = all(grid[r1-1,c] == wall_color for c in range(c1, c2+1))
                        if top_wall_ok:
                            has_complete_wall = True

                    # Bottom wall
                    if r2 + 1 < h:
                        bottom_wall_ok = all(grid[r2+1,c] == wall_color for c in range(c1, c2+1))
                        if bottom_wall_ok:
                            has_complete_wall = True

                    if has_complete_wall and rect_area > best_size:
                        best_size = rect_area
                        best_rect = (r1, r2, c1, c2)

    return best_rect, best_size

