    for r1 in range(h):
        for c1 in range(w):
            # Expand right until blocked
            max_c = c1
            while max_c + 1 < w and grid[r1][max_c+1] == bg_color:
                max_c += 1

            # Expand down until blocked  
            max_r = r1
            while max_r + 1 < h and all(grid[k][c1:c1+max_c-c1+1].tolist() == [bg_color] * (max_c-c1+1) for k in range(r1, max_r)):
                max_r += 1

            # Check if touches edge
            touches_edge = (r1 == 0 or r1 + (max_r-r1+1) == h or 
                          c1 == 0 or c1 + (max_c-c1+1) == w)

            if touches_edge:
                rectangles.append((r1, r1+max_r-r1+1, c1, max_c))

    return rectangles

